// Parse RSS XML and extract articles
const items = $input.all();
const articles = [];

for (const item of items) {
  const data = item.json.data || item.json.body || item.json;
  let text = typeof data === 'string' ? data : JSON.stringify(data);

  // Simple RSS XML parser
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(text)) !== null) {
    const content = match[1];
    const title = (content.match(/<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s) || [])[1] || '';
    const link = (content.match(/<link[^>]*>(.*?)<\/link>/s) || [])[1] || '';
    const desc = (content.match(/<description[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s) || [])[1] || '';
    const pubDate = (content.match(/<pubDate>(.*?)<\/pubDate>/s) || [])[1] || '';

    if (title) {
      articles.push({
        json: {
          title: title.replace(/<[^>]*>/g, '').trim(),
          link: link.trim(),
          description: desc.replace(/<[^>]*>/g, '').trim().substring(0, 300),
          pubDate: pubDate,
          source: 'rss'
        }
      });
    }
  }
}

return articles.length > 0 ? articles : [{json: {title: 'No articles found', source: 'error'}}];

const items = $input.all();
const keywords = {
  high: ['ai 에이전트', 'llm', 'claude', 'gpt', 'openai', 'anthropic', 'gemini',
         '자동화', 'automation', 'agi', 'transformer', '반도체', 'nvidia', 'gpu',
         'n8n', 'workflow', 'agent', 'chatbot', 'openclaw'],
  medium: ['스타트업', 'api', 'saas', '클라우드', 'cloud', 'docker',
           'kubernetes', '핀테크', 'fintech', 'react', 'node.js', 'python',
           'machine learning', '머신러닝', 'deep learning', '딥러닝'],
  context: ['한국', 'korea', 'samsung', 'kakao', 'naver', '네이버', '카카오']
};

const seen = new Set();
const scored = [];

for (const item of items) {
  const title = (item.json.title || '').toLowerCase();
  const desc = (item.json.description || '').toLowerCase();
  const text = title + ' ' + desc;

  // Dedup
  const key = title.replace(/[^a-z가-힣0-9]/g, '').substring(0, 40);
  if (seen.has(key) || !title || title === 'no articles found') continue;
  seen.add(key);

  // Score
  let score = 0;
  keywords.high.forEach(k => { if (text.includes(k)) score += 3; });
  keywords.medium.forEach(k => { if (text.includes(k)) score += 1; });
  keywords.context.forEach(k => { if (text.includes(k)) score += 1; });

  // Recency bonus
  const pubDate = new Date(item.json.pubDate || Date.now());
  const hoursAgo = (Date.now() - pubDate.getTime()) / 3600000;
  if (hoursAgo < 6) score += 3;
  else if (hoursAgo < 24) score += 1;

  if (score >= 3) {
    scored.push({
      json: {
        title: item.json.title,
        link: item.json.link,
        score: score,
        grade: score >= 7 ? 'A' : score >= 4 ? 'B' : 'C',
        description: item.json.description,
        pubDate: pubDate.toISOString()
      }
    });
  }
}

scored.sort((a, b) => b.json.score - a.json.score);
return scored.slice(0, 15);

const news = $('Score & Filter').all();
let finance = {};
let exchange = {};

try {
  finance = $('Korean Market').first().json;
} catch(e) { finance = {error: 'unavailable'}; }

try {
  exchange = $('Exchange Rate').first().json;
} catch(e) { exchange = {error: 'unavailable'}; }

const gradeA = news.filter(n => n.json.grade === 'A');
const gradeB = news.filter(n => n.json.grade === 'B');

const now = new Date().toLocaleDateString('ko-KR', {timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short'});

let report = `📊 Morning Brief | ${now}\n\n`;
report += `━━━ 🔥 TOP 핵심 뉴스 ━━━\n`;
gradeA.forEach((n, i) => {
  report += `${i+1}. ${n.json.title}\n   ${n.json.link}\n`;
});

if (gradeB.length > 0) {
  report += `\n━━━ 📰 주요 뉴스 ━━━\n`;
  gradeB.slice(0, 5).forEach((n, i) => {
    report += `• ${n.json.title}\n`;
  });
}

const krw = exchange.rates ? exchange.rates.KRW : 'N/A';
report += `\n━━━ 💰 Finance ━━━\n`;
report += `• 원/달러: ${krw}\n`;

report += `\n━━━ 📋 수집 통계 ━━━\n`;
report += `• A등급: ${gradeA.length}건 | B등급: ${gradeB.length}건\n`;
report += `• 총 필터링 통과: ${news.length}건\n`;

return [{ json: { report, newsCount: news.length, timestamp: new Date().toISOString() } }];
